    private EngineeringPhysicalOrigin Physical(BranchSnapshot s,string region)
    {var f=Facility(region);var a=Actor(s);var g=WorksiteGeometry[f.PhysicalSpot.Split('.')[0]];var r=BranchOperations.Entity(s,"readiness:"+f.Tower);Require(a.Scene==g.Id&&g.Spots.Any(x=>x.Id==f.PhysicalSpot&&a.Position.Distance(x.Stand)<=2.5)&&new Mist.Core.Exploration.NavigationGrid(g).CanStand(a.Position,true),"请实际到达 "+f.PhysicalSpot+" 工位；通信台和地区图标不能代替到场。");Require(Closed(s,f.PriorQuest)&&BranchOperations.Read<TowerReadiness>(s,"readiness:"+f.Tower) is{Safe:true},"该地区实际主线和当前塔站安全未共同成立。");var previous=s.Receipts.Single(x=>x.SemanticKey==f.PriorQuest+":resolution");Require(previous.ActionType is "tidegate_vessel_handover" or "chapter_two_archive_handover_received" or "chapter_three_tower_handover_received" or "glasshaven_technical_handover_received" or "old_city_joint_handover_received" or "main_quest_resolution","地区保全依据必须来自真实主线生产者。");return new(region,a.Scene,f.PhysicalSpot,a.Position,VoyageRules.Hash(g),previous.ReceiptId,r!.Revision,a.ActionClock);}
