    public async ValueTask<CommandResult> InspectFacilityAsync(string region,string contractVersion,string installer,string[] watchPosts,string[] serialIds)
    {
        var s=await _repository.SnapshotAsync();Safe(s,false);Editable(s);var f=Facility(region);var origin=Physical(s,region);Require(contractVersion==f.Version&&installer==f.Installer&&watchPosts.Order().SequenceEqual(f.WatchPosts.Order()),"原合同版本、合格安装班组和两个不同地方岗位不符。");var ids=Engineering.Rules.Sources.Values.Where(x=>x.Id.StartsWith("BASE-"+f.Tower+"-",StringComparison.Ordinal)).SelectMany(x=>Enumerable.Range(1,x.Quantity).Select(n=>StockId(x.Id,n))).Order().ToImmutableArray();Require(ids.SequenceEqual(serialIds.Order())&&ids.Length==4,"四件基础实物序号不能用私人零件、旧实验夹具或可选货箱替代。");string ownerPrefix=region=="R6"?"R6-S07:received_base":region+":facility:";Require(ids.All(id=>s.Items.Any(i=>i.Id==id&&i.OwnerKind=="warehouse"&&(region=="R6"?i.OwnerId==ownerPrefix:i.OwnerId.StartsWith(ownerPrefix,StringComparison.Ordinal)))),"该地区四件实物尚未真实交付或已消耗。");
        var safety=s.Receipts.Where(r=>r.ActionType=="tower_safety_verified").Select(r=>(Receipt:r,Safety:StrictJson.Deserialize<TowerSafety>(r.ResultJson))).LastOrDefault(x=>x.Safety.Tower==f.Tower&&x.Safety.Safe).Receipt??throw new InvalidOperationException("没有实际塔站安全来源。");var inspected=new FacilityInspection(region,f.Version,origin.PriorQuestReceipt,safety.ReceiptId,ids,f.WatchPosts,origin.SafetyRevision);return await Commit(s,"facility_conservation_contract_inspected",[BranchOperations.Change(s,"R6:facility:"+region,"facility_inspection",inspected),BranchOperations.Change(s,"R6:origin:"+region,"physical_origin",origin)],new{inspection=inspected,origin,capacity=1,qualification_source=f.Version},"R6:facility:"+region+":"+f.Version+":"+origin.SafetyRevision);
    }
