    public ValueTask<CommandResult> InspectProcurementStepAsync(string sourceId,int step,string work,string[] serialIds)=>WithForeground(()=>InspectProcurementStepAsyncCore(sourceId,step,work,serialIds));
    private async ValueTask<CommandResult> InspectProcurementStepAsyncCore(string sourceId,int step,string work,string[] serialIds)
    {
        var s=await _repository.SnapshotAsync();Safe(s,false);Editable(s);var source=Engineering.Rules.Sources.GetValueOrDefault(sourceId)??throw new InvalidOperationException("未公开的有限来源不能采购。");var origin=Physical(s,source.Region);Inspected(s,source.Region);
        string[] required=sourceId.StartsWith("BASE-",StringComparison.Ordinal)?["match_contract_serials","check_and_deliver_components"]:sourceId switch{"SUP-CTRL"=>["inspect_retained_technical_record","match_controller_serials","local_controller_acceptance","deliver_accepted_controllers"],"SUP-COUP"=>["inspect_retained_spare_scope","match_coupler_serials","local_coupler_acceptance","deliver_accepted_couplers"],"SUP-TEST"=>["inspect_fixture_dedication","check_independent_fixture_serials","deliver_reusable_fixtures"],_=>["inspect_transition_stock","check_protected_supply_boundary","deliver_transition_crates"]};
        Require(step>=1&&step<=required.Length&&required.Length==source.RequiredSteps&&work==required[step-1],"规定实物步骤或合同次序不符。");var ids=Enumerable.Range(1,source.Quantity).Select(n=>StockId(sourceId,n)).ToImmutableArray();Require(serialIds.Order().SequenceEqual(ids.Order()),"必须匹配这一有限原批次全部序号。");if(sourceId=="SUP-CTRL")Require(BranchOperations.Read<TechnicalPackage>(s,"technical-package") is{Verified:true,Version:TechnicalVersion},"控制器生产须当前实际技术包，不消费保留的旧失败报告。");
        var progress=BranchOperations.Read<ProcurementProgress>(s,"procurement:"+sourceId);if(progress?.Delivered==true)return new(CommitStatus.AlreadyCommitted,null,[]);Require(step==(progress?.Step??0)+1,"只能实际核验当前下一采购步骤。");string owner=sourceId.StartsWith("BASE-TWR-R6-",StringComparison.Ordinal)?"R6-S07:received_base":source.Region+":facility:"+sourceId;string key="R6:physical-procurement:"+sourceId+":"+step;
        var pending=s.Receipts.SingleOrDefault(r=>r.SemanticKey==key&&r.ActionType=="engineering_procurement_step_verified");
        if(pending is not null)
        {
            // The physical transaction may survive a process failure before the inventory consumer.
            // Resume only that immutable proof; never consume another batch or manufacture a new one.
            var physical=BranchOperations.Read<PhysicalProcurement>(s,key)??throw new InvalidOperationException("断点实物证明缺少同体现场记录。");var recorded=StrictJson.Deserialize<ProcurementStep>(pending.ResultJson);
            Require(physical.Source==sourceId&&physical.Step==step&&physical.WorkReceipt==work&&physical.SerialIds.Order().SequenceEqual(ids.Order())&&physical.Origin.Region==origin.Region&&physical.Origin.Scene==origin.Scene&&physical.Origin.Spot==origin.Spot&&physical.Origin.GeometrySha256==origin.GeometrySha256&&physical.Origin.PriorQuestReceipt==origin.PriorQuestReceipt&&physical.Origin.SafetyRevision<=origin.SafetyRevision&&recorded==new ProcurementStep(sourceId,step,source.Region,"physical:"+work+":"+origin.GeometrySha256),"恢复回执的来源、现场、合同步骤或实物序号不符。");
            Require(ids.All(id=>s.Items.Any(i=>i.Id==id&&(step==source.RequiredSteps?i.OwnerKind=="consumed"&&i.OwnerId=="engineering-stock:"+sourceId:i.OwnerKind=="warehouse"&&i.OwnerId==owner))),"断点回执的原实物归属改变，不能借另一批入账。");
            return await Engineering.ConsumeProcurementStepAsync(pending.ReceiptId);
        }
        Require(ids.All(id=>s.Items.Any(i=>i.Id==id&&i.OwnerKind=="warehouse"&&i.OwnerId==owner)),"原有限物品不在已验仓库或已使用，不能再入账。");var itemChanges=step==source.RequiredSteps?ids.Select(id=>{var i=s.Items.Single(x=>x.Id==id);return new ItemChange(i.Id,i.DefinitionId,i.OwnerKind,i.OwnerId,"consumed","engineering-stock:"+sourceId,null);}).ToImmutableArray():[];
        var payload=new ProcurementStep(sourceId,step,source.Region,"physical:"+work+":"+origin.GeometrySha256);var proof=await Commit(s,"engineering_procurement_step_verified",[BranchOperations.Change(s,"R6:physical-procurement:"+sourceId+":"+step,"physical_procurement",new PhysicalProcurement(sourceId,step,origin,ids,work))],payload,"R6:physical-procurement:"+sourceId+":"+step,itemChanges);Require(proof.Status is CommitStatus.Committed or CommitStatus.AlreadyCommitted,"实物步骤因来源变动未提交。");string receipt=proof.Receipt?.Id.Value.ToString()??(await _repository.SnapshotAsync()).Receipts.Single(r=>r.SemanticKey=="R6:physical-procurement:"+sourceId+":"+step).ReceiptId;return await Engineering.ConsumeProcurementStepAsync(receipt);
    }
